#include <bits/stdc++.h>
using namespace std;
int main() {
	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	long H, W, h, w, n;
	cin >> H >> W >> h >> w >> n;
	vector<tuple<long, long, bool>> g;
	g.reserve(2 * n);
	for (int i = 0; i < n; i++) {
		long r, c;
		cin >> r >> c;
		r--, c--;
		g.push_back({r - h + 1, c - w + 1, true});
		g.push_back({r + 1, c - w + 1, false});
	}
	sort(g.begin(), g.end());
	multiset<long> s;
	s.insert(-w);
	s.insert(W - w + 1);
	long ans = (H - h + 1) * (W - w + 1);
	auto gap = [&](long l, long r) { return max(0L, r - l - w); };
	const long Y = W - w + 1;
	const long X = H - h + 1;
	long good = Y;
	auto add = [&](long x) {
		auto it = s.lower_bound(x);
		long r = *it, l = *prev(it);
		good += gap(l, x) + gap(x, r) - gap(l, r);
		s.insert(x);
	};
	auto del = [&](long x) {
		auto it = s.find(x);
		long r = *next(it), l = *prev(it);
		good -= gap(l, x) + gap(x, r) - gap(l, r);
		s.erase(it);
	};
	long pre = 0;
	int i = 0;
	while (i < 2 * n) {
		const long x = get<0>(g[i]);
		const long nx = min(x, X);
		if (pre < nx) {
			ans -= (nx - pre) * (Y - good);
			pre = nx;
		}
		while (i < 2 * n && get<0>(g[i]) == x) {
			auto [r, c, in] = g[i];
			if (in) add(c);
			else del(c);
			i++;
		}
	}
	if (pre < X) ans -= (X - pre) * (Y - good);
	cout << ans << endl;
}
